const D = { energy: .5, scale: 1, density: .55, speed: 1, pack: .5, haze: .55, hue: 205, x: .42, y: .5, style: 'overcast', act: 'drift', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 205;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NR = 4;                                    // depth ranks, 0 = farthest

const STY = {
  // flat grey overcast polar light, white bergs, slate sea
  overcast:    { skT:[206,16,66], skB:[200,10,82], haze:[200,10,80], ice:[200,8,94], iceS:[204,26,66],
                 blue:[200,60,58], water:[204,36,22], glint:[200,6,99], grain:16, sonar:0 },
  // blue hour twilight, the bergs glow
  bluehour:    { skT:[236,54,16], skB:[214,36,40], haze:[214,26,44], ice:[210,20,72], iceS:[214,44,44],
                 blue:[210,72,50], water:[220,50,14], glint:[204,16,86], grain:14, sonar:0 },
  // midnight sun grazing low, amber berg tops, long light
  midsun:      { skT:[30,30,44], skB:[40,44,76], haze:[38,30,66], ice:[40,20,90], iceS:[24,40,58],
                 blue:[200,52,52], water:[34,30,34], glint:[46,26,99], grain:18, sonar:0 },
  // ABSTRACTED sonar/chart: cyan returns + berg outlines, no photo shading
  sonar:       { skT:[190,50,8], skB:[188,38,14], haze:[188,30,16], ice:[168,60,80], iceS:[176,50,60],
                 blue:[160,64,64], water:[190,44,10], glint:[150,40,96], grain:5, sonar:1 },
  // ABSTRACTED sumi ink: silhouettes + tonal wash
  ink:         { skT:[30,5,88], skB:[30,3,80], haze:[30,3,82], ice:[30,3,92], iceS:[30,6,58],
                 blue:[30,6,58], water:[30,5,60], glint:[30,2,96], grain:28, sonar:0 }
};
const st = STY[P.style] || STY.overcast;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const wy = height * P.y;                          // sea horizon
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.fog.remove(); }
  S.sky = mk(W, H); S.fog = mk(W, H);

  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < Math.ceil(wy); yy++) { const c = L3(cT, cB, Math.pow(yy / Math.max(1, wy), .7)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  // --- bergs across the ranks ---
  S.bergs = [];
  for (let L = 0; L < NR; L++) {
    const near = L / (NR - 1);
    const rankWY = wy + u * (.005 + near * .12);   // waterline for this rank
    const nb = Math.floor((2 + near * 3) + P.density * (2 + near * 5));
    for (let i = 0; i < nb; i++) {
      const bw = u * (.06 + fr(L * 30 + i + 3) * .16) * (.4 + near * 1.4) * P.scale;
      const bh = bw * (.25 + fr(L * 30 + i + 5) * .35);
      const prof = [];
      const nT = 4 + Math.floor(fr(L * 30 + i + 7) * 5);
      for (let t = 0; t <= nT; t++) prof.push((fr(L * 30 + i * 3 + t + 11) - .5) * bh * .5);   // jagged top
      S.bergs.push({ L: L, near: near, x0: fr(L * 30 + i + 13) * W, wy: rankWY, w: bw, h: bh,
                     prof: prof, phase: fr(L * 30 + i + 17) * 6.283, rate: (.006 + fr(i + L) * .01) * (.4 + near),
                     tilt: (fr(L * 30 + i + 19) - .5) * .1 });
    }
  }

  // fog band (tileable)
  const fogC = sh(st.haze);
  S.fog.noStroke();
  for (let i = 0; i < 12; i++) {
    const bx = fr(i * 5 + 61) * W, by = wy - u * (.02 + fr(i * 5 + 62) * .3) + fr(i * 5 + 65) * u * .3;
    const bw = u * (.5 + fr(i * 5 + 63) * 1.1), bhh = u * (.03 + fr(i * 5 + 64) * .08);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.fog.fill(fogC[0], fogC[1] * (1 - kk * .1), Math.min(99, fogC[2] + kk * 2), 8 * (1 - kk * .2));
      S.fog.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { drift: { pack: 1, fog: 1, drift: 1 }, breakup: { pack: 1.5 + sec * .06, fog: 1, drift: 1.15 }, freeze: { pack: 1.2, fog: 1.5, drift: .5 } };
const act = ACT[P.act] || ACT.drift;
const pack = Math.max(0, Math.min(1.6, P.pack * act.pack));

noStroke();
image(S.sky, 0, 0);

// far fog band behind the bergs
const FW = S.fog.width;
const fx = ((-K.t * u * .004 * P.speed * act.fog % FW) + FW) % FW;
push(); tint(0, 0, 100, 55 * hz + 20); image(S.fog, fx - FW, -u * .05); image(S.fog, fx, -u * .05); pop();

// ---------------- the sea ----------------
const waterC = sh(st.water), glintC = sh(st.glint), iceC = sh(st.ice), iceS = sh(st.iceS), blueC = sh(st.blue);
fill(waterC[0], waterC[1], waterC[2]); rect(0, wy, width, height - wy);
const nsw = Math.floor(16 + P.density * 18);
noFill();
for (let i = 0; i < nsw; i++) {
  const f = Math.pow((i + .5) / nsw, 1.8);
  const yy = wy + f * (height - wy);
  const d = Math.max(.04, f);
  const ph = K.t * (.28 + d * .5) * P.speed;
  strokeWeight(Math.max(.5, u * .0014 * (.3 + d * 2)));
  stroke(waterC[0], waterC[1] * .7, Math.min(99, waterC[2] + 12 + 14 * d), 22 + 28 * d);
  beginShape();
  for (let x = -10; x <= width + 10; x += Math.max(8, 18 * d)) {
    const w1 = Math.sin(x * .008 / (1 + d) + ph) * .7 + Math.sin(x * .02 - ph * 1.43 + i) * .3 + Math.sin(x * .0033 + K.t * .21) * .5;
    vertex(x, yy + w1 * u * .006 * d * (.5 + en));
  }
  endShape();
}
noStroke();

// ---------------- the bergs, farthest first, each drifting at its own rate ----------------
const drift = 0.9 * Math.sin(K.t * .16) + 0.5 * Math.sin(K.t * .41 + 1.7) + 0.3 * Math.sin(K.t * .87);
for (let L = 0; L < NR; L++) {
  for (const b of S.bergs) {
    if (b.L !== L) continue;
    const haze = (1 - b.near) * (.55 + .4 * hz);
    const bx = ((b.x0 + K.t * u * b.rate * P.speed * act.drift * (b.tilt > 0 ? 1 : -1) + drift * u * .003 * (.3 + b.near)) % (width + u * .4) + width + u * .4) % (width + u * .4) - u * .2;
    const by = b.wy + Math.sin(K.t * (.5 + b.near) + b.phase) * u * .002 * (.3 + b.near);
    const topY = by - b.h;
    const cIce = L3(iceC, sh(st.haze), haze);
    const cShade = L3(iceS, sh(st.haze), haze * .8);
    // vertical cliff faces + tabular top
    if (st.sonar) {
      noFill(); stroke(cIce[0], cIce[1], cIce[2], 80 - haze * 40); strokeWeight(1.4);
      rect(bx - b.w / 2, topY, b.w, by - topY);
      noStroke();
    } else {
      const litL = P.x < .5;
      fill(cShade[0], cShade[1], cShade[2], 100);
      rect(bx - b.w / 2, topY, b.w, by - topY);
      fill(cIce[0], cIce[1], cIce[2], 100);        // lit face
      const lw = b.w * .55;
      rect(litL ? bx - b.w / 2 : bx + b.w / 2 - lw, topY, lw, by - topY);
      // jagged tabular top
      fill(cIce[0], cIce[1] * .8, Math.min(99, cIce[2] + 4), 100);
      beginShape();
      for (let t = 0; t < b.prof.length; t++) vertex(bx - b.w / 2 + t / (b.prof.length - 1) * b.w, topY + b.prof[t]);
      vertex(bx + b.w / 2, topY + u * .006); vertex(bx - b.w / 2, topY + u * .006);
      endShape(CLOSE);
      // blue waterline shadow + short reflection
      fill(blueC[0], blueC[1], blueC[2], (60 - haze * 30));
      rect(bx - b.w / 2, by - u * .008, b.w, u * .012);
      fill(cIce[0], 30, cIce[2], (26 - haze * 12));  // faint reflection stub
      rect(bx - b.w * .45, by, b.w * .9, b.h * .3 * (.4 + b.near));
    }
  }
}

// ---------------- brash ice / growlers drifting on the near water ----------------
const nbr = Math.floor((12 + P.density * 30) * pack);
for (let i = 0; i < nbr; i++) {
  const life = ((K.t * (.01 + fr(i * 3 + 81) * .02) * P.speed * act.drift + fr(i * 3 + 82)) % 1);
  const f = .1 + life * .9;
  const yy = wy + Math.pow(f, 1.7) * (height - wy);
  const d = Math.max(.05, Math.pow(f, 1.7));
  const bx = (fr(i * 3 + 83) * width + Math.sin(K.t * .05 + i) * u * .03 + (life - .5) * u * .12 * (fr(i) - .5) * 4 + width * 2) % width;
  const bob = Math.sin(K.t * (.6 + i * .11) + i) * u * .0016 * (.3 + d);
  const bw = u * (.006 + fr(i * 3 + 84) * .02) * (.25 + d * 1.8) * P.scale;
  if (st.sonar) { noFill(); stroke(glintC[0], 40, 90, 60); strokeWeight(1); ellipse(bx, yy + bob, bw, bw * .4); noStroke(); continue; }
  fill(iceC[0], iceC[1] * .7, iceC[2], 90);
  ellipse(bx, yy + bob, bw, bw * (.3 + fr(i) * .2));
  fill(blueC[0], blueC[1] * .8, blueC[2], 40);
  ellipse(bx, yy + bob + bw * .1, bw * .8, bw * .12);
}

// specular sheen on the near water
if (!st.sonar) {
  blendMode(ADD);
  for (let i = 0; i < Math.floor(16 + P.density * 24); i++) {
    const f = fr(i * 3 + 91);
    const yy = wy + Math.pow(f, 1.5) * (height - wy);
    const gx = (fr(i * 3 + 92) * width + Math.sin(K.t * (.3 + f) + i) * u * .03) % width;
    const tw = Math.sin(K.t * (.8 + fr(i)) + i) * .5 + .5;
    fill(glintC[0], glintC[1] * .4, glintC[2], (6 + 16 * tw * en) * (.3 + f));
    ellipse(gx, yy, u * .012 * (.4 + f), u * .002);
  }
  blendMode(BLEND);
}

// near fog rolling across
const fx2 = ((-K.t * u * .008 * P.speed * act.fog % FW) + FW) % FW;
push(); tint(0, 0, 100, 45 * hz + 20); image(S.fog, fx2 - FW, u * .1); image(S.fog, fx2, u * .1); pop();

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.water[0], st.water[1] * .4, fr(i * 3 + 403) > .5 ? 92 : 8, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.water)[0], st.water[1], 6, 16 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.water)[0], st.water[1] * .5, 6, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
